using Crownfall.StatusEffects; using UnityEngine; namespace Crownfall.Skills { [CreateAssetMenu(fileName="StatusEffect",menuName="Crownfall/Skills/Effects/Apply Status")] public sealed class ApplyStatusEffectDefinition:SkillEffectDefinition { public StatusDefinition status; [Min(1)]public int stacks=1; public bool enemiesOnly=true; public override void Execute(SkillContext c,Crownfall.Units.Unit t){if(t!=null&&(!enemiesOnly||t.Team!=c.Caster.Team))t.Statuses.Apply(status,c.Caster,stacks);} } }
